'use strict';

// MODULES //

var isInt64 = require( '@stdlib/assert-is-int64' );
var Int64 = require( '@stdlib/number-int64-ctor' );
var format = require( '@stdlib/string-format' );


// MAIN //

/**
* Converts a value to a 64-bit signed integer.
*
* @private
* @param {*} value - value to convert
* @returns {(Int64|TypeError)} 64-bit signed integer or an error
*/
function scalarToInt64( value ) {
	if ( isInt64( value ) ) {
		return value;
	}
	try {
		return new Int64( value );
	} catch ( err ) { // eslint-disable-line no-unused-vars
		return new TypeError( format( 'invalid argument. Value must be either a 64-bit signed integer or a value which can be converted to a 64-bit signed integer. Value: `%s`.', value ) );
	}
}


// EXPORTS //

module.exports = scalarToInt64;
